"""Create a readable PDF companion to the QSAR research report."""
from __future__ import annotations
import json
from pathlib import Path
import pandas as pd
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, Image

ROOT=Path(__file__).resolve().parents[1]; RESULTS=ROOT/'results'; OUT=ROOT/'reports'/'QSAR_Research_Report.pdf'
S=getSampleStyleSheet(); NAVY=colors.HexColor('#17365D'); BLUE=colors.HexColor('#1768E5'); TEXT=colors.HexColor('#1D2939'); LINE=colors.HexColor('#D5DCE5')
for name,parent,size,lead,color in [('RTitle','Title',24,29,NAVY),('RH1','Heading1',16,20,NAVY),('RH2','Heading2',11,14,NAVY),('RBody','BodyText',9,13,TEXT),('RSmall','BodyText',7.1,9,TEXT)]: S.add(ParagraphStyle(name=name,parent=S[parent],fontName='Helvetica-Bold' if name in ['RTitle','RH1','RH2'] else 'Helvetica',fontSize=size,leading=lead,textColor=color,spaceAfter=7))
S.add(ParagraphStyle(name='Callout',parent=S['RBody'],backColor=colors.HexColor('#EEF5FF'),borderColor=colors.HexColor('#9FC3F5'),borderWidth=.5,borderPadding=7,spaceAfter=8))
P=lambda x,style='RBody': Paragraph(str(x),S[style])
def table(rows,widths):
 t=Table(rows,colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('GRID',(0,0),(-1,-1),.3,LINE),('BACKGROUND',(0,0),(-1,0),NAVY),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),7),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),3),('RIGHTPADDING',(0,0),(-1,-1),3),('TOPPADDING',(0,0),(-1,-1),3),('BOTTOMPADDING',(0,0),(-1,-1),3),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F7F9FC')]) ]));return t
def fig(path,caption):
 p=RESULTS/path
 if p.exists(): return [Image(str(p),width=165*mm,height=92*mm,kind='proportional'),P(caption,'RSmall'),Spacer(1,3*mm)]
 return []
def footer(c,doc):
 c.saveState();w,h=A4;c.setStrokeColor(LINE);c.line(18*mm,14*mm,w-18*mm,14*mm);c.setFont('Helvetica',7);c.setFillColor(NAVY);c.drawString(18*mm,9*mm,'QSAR-X research report');c.drawRightString(w-18*mm,9*mm,f'Page {doc.page}');c.restoreState()
def main():
 metrics=pd.read_csv(RESULTS/'metrics'/'registered_target_scaffold_test_metrics.csv').sort_values('gene');audit=pd.read_csv(RESULTS/'tables'/'dataset_quality_audit.csv').sort_values('gene');external=pd.read_csv(RESULTS/'validation'/'external_validation_inventory.csv').sort_values('gene');manifest=json.loads((RESULTS/'validation'/'reproducibility_manifest.json').read_text());summary=json.loads((RESULTS/'metrics'/'evaluation_summary.json').read_text());jak=metrics[metrics.gene=='JAK'].iloc[0];random=pd.read_csv(RESULTS/'validation'/'JAK_random_vs_scaffold_comparison.csv')
 story=[Spacer(1,25*mm),P('Machine Learning Based QSAR Modeling for Kinase Drug Discovery','RTitle'),P('Model Development Validation Interpretability and Applicability Domain Assessment','RH2'),Spacer(1,5*mm),P('Abstract','RH1'),P(f'This report evaluates the existing QSAR-X repository without replacing any candidate models. It recomputes predictions from 21 registered model artifacts on their saved scaffold-held-out test partitions. Mean internal scaffold-test R2 was {summary["mean_internal_scaffold_R2"]:.3f} and mean RMSE was {summary["mean_internal_scaffold_RMSE"]:.3f} pIC50. These are regression metrics, not biological or clinical accuracy. Strict external quality gates passed for 0 of 21 models.'),P('<b>Current scientific status:</b> target-specific research screening models. No registered model is represented as commercially or prospectively validated.','Callout'),P('Contents','RH2'),P('1 Project audit and provenance<br/>2 Data QC and molecular representation<br/>3 Internal scaffold test results<br/>4 JAK pooled model evaluation<br/>5 Applicability domain and interpretability<br/>6 External validation and limitations<br/>7 Reproducibility and references'),PageBreak(),P('1 Project audit and provenance','RH1'),P('The repository contains ChEMBL IC50 collection and curation scripts, RDKit structural processing, versioned model files, split assignments, cross-validation comparisons, external evidence reports, a FastAPI prediction service, and a React dashboard. The 20 target-specific models use curated IC50 records converted to pIC50 = 9 - log10(IC50 in nM). The additional JAK candidate uses a user-provided pChEMBL dataset and is retained as a pooled family endpoint.'),table([[P('Audit item','RSmall'),P('Result','RSmall')],[P('Registered models','RSmall'),P('21: 20 ChEMBL target-specific and 1 pooled JAK','RSmall')],[P('Molecular representation','RSmall'),P('RDKit Morgan fingerprint, radius 2, 2,048 bits','RSmall')],[P('Validation partition','RSmall'),P('Saved scaffold-held-out internal test','RSmall')],[P('External gates passed','RSmall'),P('0','RSmall')]], [58*mm,116*mm]),P('2 Data quality control','RH1'),P('The evaluator checks clean inputs for missing pIC50, duplicate canonical structures, RDKit parse failures, and exact canonical-structure leakage between development and scaffold-test sets. Model SHA256 checksums are retained in the machine-readable audit.'),table([[P('Gene','RSmall'),P('Clean n','RSmall'),P('Missing','RSmall'),P('Duplicates','RSmall'),P('Dev-test overlap','RSmall')]]+[[P(r.gene,'RSmall'),P(int(r.n_clean_unique_structures),'RSmall'),P(int(r.missing_pIC50),'RSmall'),P(int(r.duplicate_canonical_smiles),'RSmall'),P(int(r.development_test_structure_overlap),'RSmall')] for _,r in audit.iterrows()],[30*mm,32*mm,30*mm,34*mm,48*mm]),PageBreak(),P('3 Internal scaffold test evaluation','RH1'),P('Existing candidate algorithms were selected using training-only scaffold-grouped CV. For this report, every saved model was loaded and used to recompute its saved scaffold-test predictions. R2, RMSE, MAE, median absolute error, explained variance, Pearson r, Spearman rho, residuals, and bootstrap intervals are written as structured output. The values below are internal validation only.'),table([[P('Gene','RSmall'),P('Model','RSmall'),P('n','RSmall'),P('R2','RSmall'),P('RMSE','RSmall'),P('MAE','RSmall'),P('Spearman','RSmall')]]+[[P(r.gene,'RSmall'),P(r.selected_model,'RSmall'),P(int(r.n),'RSmall'),P(f'{r.R2:.3f}','RSmall'),P(f'{r.RMSE_pIC50:.3f}','RSmall'),P(f'{r.MAE_pIC50:.3f}','RSmall'),P(f'{r.Spearman_rho:.3f}','RSmall')] for _,r in metrics.iterrows()],[20*mm,29*mm,14*mm,18*mm,25*mm,24*mm,30*mm]),*fig(Path('figures/registered_model_scaffold_test_comparison.png'),'Figure 1. Recomputed internal scaffold-test performance across registered candidates.'),*fig(Path('figures/activity_distribution_by_target.png'),'Figure 2. Curated pIC50 distributions by registered target.'),PageBreak(),P('4 JAK pooled model evaluation','RH1'),P(f'The pooled JAK candidate was recomputed on {int(jak.n)} scaffold-test compounds: R2 {jak.R2:.3f}, RMSE {jak.RMSE_pIC50:.3f}, MAE {jak.MAE_pIC50:.3f}, Spearman rho {jak.Spearman_rho:.3f}. It predicts a pooled pChEMBL endpoint and cannot support JAK1/JAK2/JAK3 isoform-selectivity claims because its source has no per-row isoform label or assay metadata.'),table([[P('Split','RSmall'),P('R2','RSmall'),P('RMSE','RSmall'),P('MAE','RSmall')]]+[[P(r['split'],'RSmall'),P(f'{r.R2:.3f}','RSmall'),P(f'{r.RMSE_pIC50:.3f}','RSmall'),P(f'{r.MAE_pIC50:.3f}','RSmall')] for _,r in random.iterrows()],[72*mm,31*mm,36*mm,35*mm]),*fig(Path('figures/JAK_scaffold_test_diagnostics.png'),'Figure 3. JAK observed-versus-predicted, residual, and absolute-error diagnostics.'),*fig(Path('figures/JAK_descriptor_distributions.png'),'Figure 4. RDKit descriptor distributions for pooled JAK structures.'),*fig(Path('figures/JAK_descriptor_correlation_heatmap.png'),'Figure 5. Descriptor correlation heatmap for pooled JAK structures.'),PageBreak(),P('5 Applicability domain and interpretability','RH1'),P(f'The JAK applicability-domain file calculates maximum Morgan Tanimoto similarity to the development chemistry for a reproducible 25-compound scaffold-test sample. The sample 5th-percentile threshold is {manifest["JAK_deep_dive"]["AD_test_similarity_threshold_5th_percentile"]:.3f}. This is an empirical internal alert threshold and is not a calibrated probability of correctness. A focused held-out permutation analysis evaluates the 20 highest native-importance fingerprint bits on a fixed 100-compound scaffold-test sample. It is a local sensitivity diagnostic, not a causal potency mechanism or stability analysis.'),*fig(Path('interpretability/JAK_targeted_permutation_importance.png'),'Figure 6. Targeted held-out permutation importance for high native-importance fingerprint bits.'),*fig(Path('applicability_domain/JAK_similarity_distribution.png'),'Figure 7. JAK nearest-development similarity distribution for the evaluated sample.'),P('6 External validation and limitations','RH1'),P('External validation requires compatible endpoint and units, exact relation, assay context, provenance, structural and publication independence, sufficient sample size, and predefined performance thresholds. The project keeps exploratory external-source checks, but none pass every gate.'),table([[P('Gene','RSmall'),P('Source','RSmall'),P('n','RSmall'),P('RMSE','RSmall'),P('Spearman','RSmall'),P('Pass','RSmall')]]+[[P(r.gene,'RSmall'),P(str(r.source),'RSmall'),P(str(r.n_nonoverlap),'RSmall'),P(f'{r.RMSE_pIC50:.3f}' if pd.notna(r.RMSE_pIC50) else '-','RSmall'),P(f'{r.Spearman:.3f}' if pd.notna(r.Spearman) else '-','RSmall'),P(str(r.quality_gates_passed),'RSmall')] for _,r in external.iterrows()],[25*mm,43*mm,16*mm,29*mm,32*mm,25*mm]),P('The models rank candidate chemistry for research. They do not predict clinical efficacy, safety, or an experimental measurement for every arbitrary protein or compound. Internal scaffold testing is not independent external validation. The JAK input’s pChEMBL source cannot be called a verified IC50 dataset.'),P('7 Reproducibility and references','RH1'),P(f'Seed 42; Python {manifest["python"]}; RDKit {manifest["rdkit"]}; scikit-learn {manifest["scikit_learn"]}; NumPy {manifest["numpy"]}; pandas {manifest["pandas"]}; SciPy {manifest["scipy"]}. Recomputed predictions, residuals, figures, audit, validation inventory, model checksums, and manifests are stored under results/.'),P('OECD. Guidance Document on the Validation of (Quantitative) Structure-Activity Relationship [(Q)SAR] Models. OECD Series No. 69, 2014. https://doi.org/10.1787/9789264085442-en','RSmall'),P('RDKit documentation. The RDKit Book: Morgan and Feature Morgan fingerprints. https://www.rdkit.org/docs/RDKit_Book.html','RSmall'),P('Rogers D, Hahn M. Extended-connectivity fingerprints. J Chem Inf Model. 2010;50:742-754. https://doi.org/10.1021/ci100050t','RSmall')]
 doc=SimpleDocTemplate(str(OUT),pagesize=A4,rightMargin=18*mm,leftMargin=18*mm,topMargin=18*mm,bottomMargin=18*mm,title='Machine Learning Based QSAR Modeling for Kinase Drug Discovery',author='QSAR-X');doc.build(story,onFirstPage=footer,onLaterPages=footer);print(OUT)
if __name__=='__main__':main()
